#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, V, P;
    cin >> N >> M >> V >> P;

    vector<long long> A(N);
    for (int i = 0; i < N; ++i) cin >> A[i];

    sort(A.begin(), A.end(), greater<long long>());

    auto canBeSelected = [&](int i) -> bool {
        // If already within current top P, it can surely be selected.
        if (i < P) return true;

        // Give this problem all M votes.
        long long x = A[i] + M;

        // If even then it is still below the current P-th problem, impossible.
        if (x < A[P - 1]) return false;

        // Count how many votes are needed to make enough problems reach x.
        // Problems before i:
        // - top P-1 problems can be anything; they are already safe.
        // - problems from P-1 to i-1 must be raised up to x if possible.
        long long needed = 0;

        for (int j = P - 1; j < i; ++j) {
            needed += x - A[j];
        }

        // Problems after i can receive at most M votes each.
        // To maximize how many problems can outrank i, they can be raised up to at most A[j] + M,
        // but since A[j] <= A[i], and x = A[i] + M, they can never exceed x.
        // For the feasibility condition used in the standard solution,
        // the remaining candidates (excluding top P-1 and this i-th one) are N - i - 1.
        // Total votes available for these "competing" problems is M * (V - (P - 1)).
        long long total = 1LL * M * (V - (P - 1));

        return needed < total;
    };

    int ans = 0;
    for (int i = 0; i < N; ++i) {
        if (canBeSelected(i)) ++ans;
    }

    cout << ans << '\n';
    return 0;
}

