int cmp(const void *a, const void *b) {
    return *(int*)a - *(int*)b;
}

int main() {
    int N, M, V, P;
    scanf("%d %d %d %d", &N, &M, &V, &P);
    int scores[N];
    for (int i = 0; i < N; i++) {
        scanf("%d", &scores[i]);
    }
    qsort(scores, N, sizeof(int), cmp);

    // The P-th highest score after sorting ascending: scores[N-P]
    int threshold = scores[N-P];
    int count = 0;

    // A problem can be selected if score[i] + M >= threshold
    // But also need to check if it's possible to keep it in top P
    // when other problems get votes.

    // We'll use binary search / two-pointer to count possible problems.
    // If score[i] + M < scores[N-P], impossible.
    // Else, we need to check if we can prevent more than P-1 problems
    // from exceeding score[i]+M.

    long long totalVotes = (long long) M * V;

    for (int i = 0; i < N; i++) {
        if (scores[i] + M < scores[N-P]) continue;

        // Suppose problem i gets all M votes.
        int myScore = scores[i] + M;

        // Problems with score > myScore are already above
        int above = 0;
        for (int j = N-1; j >= 0; j--) {
            if (scores[j] > myScore) above++;
            else break;
        }
        if (above >= P) continue; // too many already above

        // Now we can give votes to others to push them above myScore
        // Each judge votes for V distinct problems, excluding i? No, i gets votes from all judges.
        // Remaining votes per judge = V-1 for other problems.
        long long otherVotes = (long long) M * (V - 1);

        // We need to see if we can push at least P - above problems above myScore
        long long needed = 0;
        int countAbove = 0;
        for (int j = N-1; j >= 0; j--) {
            if (j == i) continue;
            if (scores[j] > myScore) {
                countAbove++;
                continue;
            }
            if (countAbove >= P) break;
            // How many votes needed to make this > myScore?
            int need = myScore - scores[j] + 1;
            if (need > M) continue; // cannot reach even with all votes
            needed += need;
            countAbove++;
        }
        if (countAbove < P) {
            count++;
            continue;
        }
        if (needed <= otherVotes) {
            count++;
        }
    }

    printf("%d\n", count);
    return 0;
}

