int main() {
    int N, M, V, P;
    scanf("%d %d %d %d", &N, &M, &V, &P);

    int s[1000];
    for (int i = 0; i < N; i++) scanf("%d", &s[i]);

    int count = 0;
    for (int i = 0; i < N; i++) {
        int max_score_i = s[i] + M;
        // Count problems that always beat i
        int always_beat = 0;
        for (int j = 0; j < N; j++) {
            if (j == i && s[j] > max_score_i) always_beat++;
            if (j != i && s[j] > max_score_i) always_beat++;
        }
        if (always_beat >= P) continue;

        // Remaining votes to distribute among other problems
        long long remaining = (long long)M * (V - 1);
        // Capacity of other problems to absorb votes without exceeding max_score_i
        long long capacity = 0;
        for (int j = 0; j < N; j++) {
            if (j == i) continue;
            if (s[j] <= max_score_i) {
                capacity += (max_score_i - s[j]);
                if (capacity > (long long)M * V) { capacity = (long long)M * V; break; }
            }
        }
        if (capacity >= remaining) count++;
    }

    printf("%d\n", count);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int cmp_ll_desc(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    if (x < y) return 1;
    if (x > y) return -1;
    return 0;
}

int main(void) {
    int N, M, V, P;
    if (scanf("%d %d %d %d", &N, &M, &V, &P) != 4) return 0;

    long long *A = (long long *)malloc(sizeof(long long) * N);
    for (int i = 0; i < N; i++) scanf("%lld", &A[i]);

    qsort(A, N, sizeof(long long), cmp_ll_desc);

    int guaranteed = P;  // top P are always potentially selected
    long long border = A[P - 1];

    for (int i = P; i < N; i++) {
        long long x = A[i];

        // If even after receiving all M votes, it cannot reach current P-th score,
        // then it can never be selected.
        if (x + M < border) continue;

        // Check if this problem can be in top P.
        // Assume this problem gets M votes.
        // For problems before i, each can receive at most M extra, but to keep this
        // problem within top P, only enough votes to stay above x+M matter.
        long long need = 0;

        for (int j = 0; j < N; j++) {
            if (j <= i) continue;
            // problems after i do not matter for pushing x out of top P
        }

        // Standard condition:
        // Count whether total votes can be distributed so that fewer than P problems
        // end up strictly above this problem.
        // Equivalent AtCoder ABC161 B/Candidate style check:
        //
        // For all problems in positions [0, P-2], they are certainly above or tied enough.
        // For positions [P-1, i-1], to make them exceed x+M, they need extra votes.
        //
        // We compute maximum votes that can be assigned without forcing x out.
        long long total = 0;

        for (int j = 0; j < N; j++) {
            if (j < P - 1) {
                total += M;
            } else if (j < i) {
                long long add = x + M - A[j];
                if (add < 0) add = 0;
                if (add > M) add = M;
                total += add;
            } else if (j == i) {
                total += M;
            } else {
                // j > i
                // Since sorted descending, A[j] <= x, so they can receive at most
                // x+M-A[j] without surpassing x+M.
                long long add = x + M - A[j];
                if (add < 0) add = 0;
                if (add > M) add = M;
                total += add;
            }
        }

        // If even in the most favorable distribution, total possible votes assigned
        // is less than M*V, then impossible.
        // Otherwise possible.
        if (total >= 1LL * M * V) guaranteed++;
    }

    printf("%d\n", guaranteed);

    free(A);
    return 0;
}

