        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int M = sc.nextInt();
        int V = sc.nextInt();
        int P = sc.nextInt();

        int[] scores = new int[N];
        for (int i = 0; i < N; i++) {
            scores[i] = sc.nextInt();
        }

        Arrays.sort(scores);

        long totalVotes = (long) M * V;

        // The P-th highest score in sorted ascending is at index N-P
        int thresholdIndex = N - P;
        long threshold = scores[thresholdIndex];

        int count = 0;
        for (int i = 0; i < N; i++) {
            long maxScore = scores[i] + totalVotes;
            if (maxScore >= threshold) {
                count++;
            }
        }

        System.out.println(count);
    }
}

