public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt(), M = sc.nextInt(), V = sc.nextInt(), P = sc.nextInt();
        int[] s = new int[N];
        for (int i = 0; i < N; i++) s[i] = sc.nextInt();

        int count = 0;
        for (int i = 0; i < N; i++) {
            int best = s[i] + M;
            int[] others = new int[N - 1];
            int k = 0;
            for (int j = 0; j < N; j++) if (j != i) others[k++] = s[j];
            Arrays.sort(others);
            long votes = (long) M * (V - 1);
            for (int j = 0; j < N - 1 && votes > 0; j++) {
                long canAbsorb = Math.max(0, best - others[j]);
                long give = Math.min(Math.min(canAbsorb, M), votes);
                others[j] += give;
                votes -= give;
            }
            int above = 0;
            for (int j = 0; j < N - 1; j++) if (others[j] > best) above++;
            if (above < P) count++;
        }
        System.out.println(count);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();
        int V = fs.nextInt();
        int P = fs.nextInt();

        long[] a = new long[N];
        for (int i = 0; i < N; i++) a[i] = fs.nextLong();

        Arrays.sort(a); // ascending

        int answer = 0;
        for (int i = 0; i < N; i++) {
            if (canBeSelected(i, a, N, M, V, P)) answer++;
        }

        System.out.println(answer);
    }

    static boolean canBeSelected(int idx, long[] a, int N, int M, int V, int P) {
        long candidate = a[idx] + M;

        // If even after getting all M votes, candidate is still below the current P-th largest,
        // it can never enter top P.
        if (candidate < a[N - P]) return false;

        // Problems already surely above candidate after candidate gets M votes.
        // Those are problems with initial score > candidate.
        int stronger = upperBound(a, candidate); // first position > candidate
        int guaranteedAbove = N - stronger;
        if (guaranteedAbove >= P) return false;

        // Problems from idx+1 to N-P-1 are the ones that matter.
        // Top P-1 problems can always be chosen together with candidate.
        long need = 0;
        int left = idx + 1;
        int right = N - P; // inclusive
        for (int j = left; j <= right; j++) {
            need += Math.max(0L, candidate - a[j]);
        }

        // Total votes available to distribute among these problems and candidate's "competition"
        // after reserving M votes for each of the top P-1 problems:
        long available = (long) M * V - (long) M * (P - 1);

        return need < available;
    }

    static int upperBound(long[] a, long x) {
        int l = 0, r = a.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (a[mid] <= x) l = mid + 1;
            else r = mid;
        }
        return l;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            long sign = 1, val = 0;
            int c;
            do {
                c = read();
            } while (c <= ' ');

            if (c == '-') {
                sign = -1;
                c = read();
            }

            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}
